void process_sas_commands(void) {
    struct sas_command *cmd, *n;
    struct sas_task *task;
    int rc;

    list_for_each_entry_safe(cmd, n, &command_list, list) {
        task = cmd->task;
        if (task->reset_needed) {
            spin_lock_irq(&task->state_lock);
            if (task->state == SAS_TASK_STATE_RESETTING) {
                spin_unlock_irq(&task->state_lock);
                continue;
            }
            task->state = SAS_TASK_STATE_RESETTING;
            spin_unlock_irq(&task->state_lock);

            if (task->lu_reset_required) {
                rc = sas_recover_logical_unit(task);
                if (rc) {
                    printk(KERN_ERR "Failed to recover logical unit for task %p\n", task);
                } else {
                    printk(KERN_INFO "Recovered logical unit for task %p\n", task);
                }
            } else {
                rc = sas_recover_connection(task);
                if (rc) {
                    printk(KERN_ERR "Failed to recover I_T connection for task %p\n", task);
                } else {
                    printk(KERN_INFO "Recovered I_T connection for task %p\n", task);
                }
            }

            spin_lock_irq(&task->state_lock);
            task->reset_needed = 0;
            if (rc == 0) {
                task->state = SAS_TASK_STATE_READY;
            } else {
                task->state = SAS_TASK_STATE_FAILED;
            }
            spin_unlock_irq(&task->state_lock);
        }

        if (task->state == SAS_TASK_STATE_COMPLETED ||
            task->state == SAS_TASK_STATE_FAILED) {
            list_del(&cmd->list);
            sas_free_command(cmd);
        }
    }
}

void process_sas_commands(void) {
    struct sas_command *cmd, *tmp;

    list_for_each_entry_safe(cmd, tmp, &command_list, entry) {
        struct sas_task *task = cmd->task;
        unsigned long flags;

        spin_lock_irqsave(&task->state_lock, flags);

        if (task_needs_reset(task)) {
            int rc;

            if (task->state == SAS_TASK_STATE_LU_RESET) {
                rc = sas_lu_reset(task->device);
                if (rc) {
                    dev_err(&task->device->dev, "Failed to reset logical unit\n");
                } else {
                    dev_info(&task->device->dev, "Logical unit reset successfully\n");
                }
            } else if (task->state == SAS_TASK_STATE_I_T_RESET) {
                rc = sas_i_t_reset(task->device);
                if (rc) {
                    dev_err(&task->device->dev, "Failed to reset I_T nexus\n");
                } else {
                    dev_info(&task->device->dev, "I_T nexus reset successfully\n");
                }
            } else {
                dev_warn(&task->device->dev, "Unknown task reset state: %d\n", task->state);
            }

            task_clear_reset_needed(task);
        }

        spin_unlock_irqrestore(&task->state_lock, flags);
    }
}

void process_sas_commands(void) {
    struct sas_command *cmd, *n;
    struct sas_task *task;

    list_for_each_entry_safe(cmd, n, &command_list, list_entry) {
        task = cmd->task;

        if (task->reset_required) {
            if (task->state == SAS_TASK_STATE_I_T_NEXUS_LOSS) {
                /* Attempt to recover I_T connection */
                if (recover_i_t_connection(task)) {
                    log_message("I_T connection recovery successful for task %p.", task);
                    clear_task_queue(task);
                } else {
                    log_message("Failed to recover I_T connection for task %p.", task);
                }
            } else if (task->state == SAS_TASK_STATE_LOGICAL_UNIT_RESET) {
                /* Attempt to recover the logical unit */
                if (recover_logical_unit(task)) {
                    log_message("Logical unit recovery successful for task %p.", task);
                    clear_task_queue(task);
                } else {
                    log_message("Failed to recover logical unit for task %p.", task);
                }
            } else if (task->state == SAS_TASK_STATE_DEVICE_RESET) {
                /* Attempt to reset the device */
                if (reset_sas_device(task)) {
                    log_message("Device reset successful for task %p.", task);
                    clear_task_queue(task);
                } else {
                    log_message("Failed to reset device for task %p.", task);
                }
            }

            task->reset_required = 0;
        }

        /* Remove command from the list and free it */
        list_del(&cmd->list_entry);
        kfree(cmd);
    }
}

void process_sas_commands(void) {
    struct sas_command *cmd, *next;

    list_for_each_entry_safe(cmd, next, &command_list, entry) {
        struct sas_task *task = cmd->task;
        unsigned long flags;

        if (task->reset_needed) {
            spin_lock_irqsave(&task->state_lock, flags);

            if (task->state == SAS_TASK_STATE_RESETTING) {
                spin_unlock_irqrestore(&task->state_lock, flags);
                continue;
            }

            task->state = SAS_TASK_STATE_RESETTING;
            spin_unlock_irqrestore(&task->state_lock, flags);

            if (task->lu_reset_required) {
                if (recover_logical_unit(task)) {
                    SAS_LOG_INFO("LU recovery successful for task %p.\n", task);
                } else {
                    SAS_LOG_ERR("Failed to recover logical unit for task %p.\n", task);
                }
            } else {
                if (recover_i_t_connection(task)) {
                    SAS_LOG_INFO("I_T recovery successful for task %p.\n", task);
                } else {
                    SAS_LOG_ERR("Failed to recover I_T connection for task %p.\n", task);
                }
            }

            spin_lock_irqsave(&task->state_lock, flags);
            task->reset_needed = 0;
            task->state = SAS_TASK_STATE_IDLE;
            spin_unlock_irqrestore(&task->state_lock, flags);
        }

        clear_command_queue(cmd);
        list_del(&cmd->entry);
        free_sas_command(cmd);
    }
}

void process_sas_commands(void) {
    struct sas_command *cmd, *tmp;

    list_for_each_entry_safe(cmd, tmp, &command_list, list_entry) {
        struct sas_task *task = cmd->task;
        unsigned long flags;

        spin_lock_irqsave(&task->state_lock, flags);

        if (task->reset_needed) {
            if (task->state == SAS_TASK_STATE_LU_RESET) {
                if (attempt_lu_recovery(cmd)) {
                    log_message("Logical unit recovery initiated for command.");
                    task->reset_needed = 0;
                } else {
                    log_error("Failed to recover logical unit for command.");
                }
            } else if (task->state == SAS_TASK_STATE_I_T_RESET) {
                if (attempt_i_t_recovery(cmd)) {
                    log_message("I_T recovery initiated for command.");
                    task->reset_needed = 0;
                } else {
                    log_error("Failed to recover I_T connection for command.");
                }
            }

            if (!task->reset_needed) {
                clear_command_queue(cmd);
            }
        }

        spin_unlock_irqrestore(&task->state_lock, flags);

        if (task->state == SAS_TASK_STATE_DONE || task->reset_needed == 0) {
            list_del(&cmd->list_entry);
            free_command(cmd);
        }
    }
}
